/* @autogenerated */
import { booleanAttribute, Directive, Input, TemplateRef } from '@angular/core';

@Directive({
  selector: 'ng-template[localRoute]',
})
export class LocalRouteDirective {
  @Input('localRoute') on: string | undefined;
  @Input({ transform: booleanAttribute }) initial = false;
  @Input({ transform: booleanAttribute }) fallback = false;

  constructor(public template: TemplateRef<unknown>) {}

  isFallback() {
    return this.fallback;
  }

  isInitial() {
    return this.initial;
  }
}
